import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK 15b (2026-09-24): THE LEAN EXAM FILE — the eight Mishnah rows the spine cites in its own Hebrew over the two chapters, read WHOLE from the export
# (Hebrew and English) at the design, each a case of a cell with its verdict; NO Talmud segment read (the disputed rows carry both arms on the Mishnah's own line);
# coverage COMPUTED from the export's rows, never recited. The docket whole OWED (COMPILE_DEBT's lean-pass box). ls done before the write. write_ch16_exam.py's form. RUN FROM THE REPO ROOT.
import json, os, re, html, subprocess
ROOT = _ROOT
OUT = ROOT + '/logic/oral_triage/deu_17_18_shoftim_exam_2026-09-24.md'
assert not os.path.exists(OUT) or os.environ.get('DEU_REWRITE') == '1', OUT   # this sitting's own writer may rewrite its own ledger before the commit (DEU_REWRITE=1)
def clean(s): return re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', '', html.unescape(s))).strip()
GLOSS = [('halakhic', 'halakhic (of the law)'), ('halakha', 'halakha (the law)'), ('[aspanya]', '[aspanya] (the soldiers\' pay)'), ('[tzon]', '[tzon] (flock)'), ('[tzonekha]', '[tzonekha] (your flock)'), ('[peras]', '[peras] (a half)'), ('pitom', 'pitom (a ventriloquist)'), ('mishna', 'mishna (the row)'), ('mitzva', 'mitzva (the commandment)'), ('zav', 'zav (one with a discharge)'), ('karet', 'karet (cutting off)')]
def gloss(en):
    for a, b in GLOSS:
        if a in en and b not in en: en = en.replace(a, b, 1)
    return en
def row(tr, c, p):
    d = f'{ROOT}/Data/sefaria_export/Mishnah_{tr}'
    he = json.load(open(f'{d}/he.json', encoding='utf-8')); en = json.load(open(f'{d}/en.json', encoding='utf-8'))
    g = lambda x: (x['text'] if isinstance(x, dict) and 'text' in x else x)
    return clean(g(he)[c - 1][p - 1]), gloss(clean(g(en)[c - 1][p - 1]))   # the export's transliterated terms glossed once each for the lint
ROWS = [
 ('Sanhedrin', 11, 2, '17:8-13', "152:13-14 (the Mishnah cited in the spine's own Hebrew — the three courts and the appeal's formula)", 'LAW', "F3 the_high_court — the_three_courts: the court at the Temple Mount's entrance, at the courtyard's entrance, in the Chamber of Hewn Stone, the formula 'thus I expounded and thus my fellows' at each, Torah going out from the great court; the rebel elder exempt when he teaches, liable when he instructs others to act, the student exempt — THE WRITE high_court_at_the_place_commanded; the tiers a PARAMETER", "שְׁלֹשָׁה בָתֵּי דִינִין הָיוּ שָׁם (three courts were there)"),
 ('Sotah', 7, 8, '17:15', "157:10 (cited in the spine's own Hebrew — Agrippas at 'not your brother')", 'LAW', "F4 the_king — from_among_your_brothers_and_agrippas: the king's portion read at the assembly on a wooden platform; Agrippas stood to receive and read standing and the sages praised him; at 'you may not set over you a foreigner' his eyes ran with tears and all said 'you are our brother' — THE WRITE foreign_king_barred; the reading's list a DATA row", "אַגְרִיפָּס הַמֶּלֶךְ עָמַד וְקִבֵּל וְקָרָא עוֹמֵד (King Agrippas stood and received and read standing)"),
 ('Sanhedrin', 2, 4, '17:16-19', "161:1 and 161:4 (cited in the spine's own Hebrew — the copy with him everywhere; the king's road); 159:1-4 the limits", 'LAW', "F4 the_king — the_three_limits_for_himself and the_copy_of_the_law: eighteen wives (R. Judah: more unless they turn his heart; R. Simeon: even one who turns it — THREE ARMS), horses enough for his chariot, silver and gold enough for the soldiers' pay; the optional war by the seventy-one, the road without measure, the first share of the spoil; the scroll with him going out and coming in, in judgment and at table — THE WRITES wives_multiplying_barred, horses_multiplying_barred, silver_and_gold_multiplying_barred, law_copy_commanded; the numbers PARAMETERS", "לֹא יַרְבֶּה לּוֹ נָשִׁים (he shall not multiply wives for himself — the row continues: but eighteen)"),
 ('Chullin', 10, 4, '18:3', "165:5 (cited in the spine's own Hebrew — the claim at the slaughter's instant)", 'LAW', "F5 the_priests_dues — the_claim_at_the_slaughter_and_the_proselytes_cow: the convert's cow slaughtered before the conversion exempt, after it liable, in doubt exempt — the burden of proof on the claimant; the foreleg from the knee's joint to the shoulder-blade (the nazirite's), the thigh its counterpart (R. Judah to the upper joint), the jaw to the windpipe's ring — THE WRITE shoulder_cheeks_maw_owed; the members a PARAMETER", "גֵּר שֶׁנִּתְגַּיֵּר וְהָיְתָה לוֹ פָרָה (a convert who converted and had a cow)"),
 ('Chullin', 11, 2, '18:4', "166:5 and 166:6 (cited in the spine's own Hebrew, the second by 'ibid.' — the gentile's flock, the seller and the buyer, the gift's measure)", 'LAW', "F5 the_priests_dues — the_first_fruits_and_the_fleece: two ewes (Shammai — Isaiah 7:21) or five (Hillel — 1 Samuel 25:18); R. Dosa's weight against the sages' any amount; five selas in Judea, ten in Galilee, whitened not dyed, enough for a small garment; dyed before given exempt, whitened liable; the gentile's fleece exempt, the seller who kept some liable else the buyer — THE WRITE first_fleece_owed; the threshold and the measure PARAMETERS with both houses' arms", "וְכַמָּה הוּא מְרֻבֶּה (and how many is 'many')"),
 ('Zevachim', 2, 1, '18:7', "169:1 (cited in the spine's own Hebrew — the service on the floor)", 'LAW', "F6 the_levite_at_the_place — on_the_floor: the non-priest, the mourner, the immersed-that-day, the one lacking atonement, the one lacking vestments, the unwashed, the uncircumcised, the impure, the seated, the one standing on vessels, on a beast, on his fellow's feet — the blood's reception disqualified; the left hand (R. Simeon fit); the blood spilled on the floor and gathered; the ramp not opposite the base, above for below, inside for outside — disqualified without cutting off: a DATA row of the disqualifications; the standing of 155:5 and 167:1", "כָּל הַזְּבָחִים שֶׁקִּבֵּל דָּמָן זָר (all the offerings whose blood a non-priest received)"),
 ('Sukkah', 5, 7, '18:8', "169:2 (cited in the spine's own Hebrew — the watches equal at the three feasts)", 'LAW', "F6 the_levite_at_the_place — portion_as_portion: at three times in the year all the watches equal in the festival's limbs and the showbread's division; at the assembly 'here is matzah, here is leaven'; the fixed watch offers the dailies, the vows and the freewill offerings; a festival beside the Sabbath — all the watches equal in the showbread — THE WRITE equal_portions_commanded; the equality a PARAMETER", "בִּשְׁלשָׁה פְרָקִים בַּשָּׁנָה הָיוּ כָּל מִשְׁמָרוֹת שָׁווֹת (at three times in the year all the watches were equal)"),
 ('Sanhedrin', 7, 7, '18:10-11', "171:3 (fire and Molech joined — both required) and 172:2 (cited in the spine's own Hebrew — the python from the armpit)", 'LAW', "F7 the_diviners — the_court_warned_and_fire_with_molech and the_charmer_the_ghost_the_spirit_the_dead: the giver to Molech liable only when he hands over AND passes through the fire, neither alone; the ghost-master the python speaking from his armpit, the familiar spirit the speaker from his mouth — stoned; the one who asks of them under a warning — THE WRITES passing_through_fire_barred, ghost_consulting_barred, familiar_spirit_barred; the two penalties a PARAMETER", "הַנּוֹתֵן מִזַּרְעוֹ לַמֹּלֶךְ (one who gives of his seed to Molech)"),
]
read = [(tr, c, p) + row(tr, c, p) for tr, c, p, *_ in ROWS]
for (tr, c, p, he, en), r in zip(read, ROWS):
    assert re.sub(r'[^א-ת]', '', r[7].split(' (')[0]) in re.sub(r'[^א-ת]', '', he), (tr, c, p, 'the opening typed from the row')   # the typed Hebrew opening found in the row's consonants
L = []
L.append("# THE LEAN EXAM — Deuteronomy 17:1-18:22 (the blemished sacrifice; the idolater's trial with two witnesses and the witnesses' hand; the high court at the place, the sentence binding right or left, the rebel elder; the king from among the brothers with his three limits and his copy of the law; the priests' portion and their dues — the shoulder, the cheeks, the maw, the firsts and the fleece; the Levite from the gates at the place, portion as portion; the diviners barred, whole with the LORD; the prophet like Moses, Horeb's request, the false prophet and the test by the event) — THE DEUTERONOMY WALK sitting 15b, THE LEAN PASS (2026-09-24; DEUTERONOMY_WALK.md \"Sitting 15b — THE COMPILE OF CHAPTERS 17-18 … LEAN\" THE FORM)")
L.append("# DECLARED (THE LEAN PASS, owner-ruled 2026-09-23 — DEUTERONOMY_WALK.md \"THE LEAN PASS\"; the state doc's #208): NO DOCKET at this sitting — the testing shelf's cases are THE MISHNAH ROWS THE SPINE CITES IN ITS OWN HEBREW at the reading (logic/oral_triage/deu_17_18_shoftim_2026-09-24.md — rows 152:13, 157:10, 161:1, 161:4, 165:5, 166:5, 166:6 (ibid.), 169:1, 169:2, 172:2 and the finds), EIGHT rows: Mishnah Sanhedrin 11:2, Sotah 7:8, Sanhedrin 2:4, Chullin 10:4, Chullin 11:2, Zevachim 2:1, Sukkah 5:7, Sanhedrin 7:7 — each read WHOLE from the export (Data/sefaria_export/Mishnah_<tractate>/he.json and en.json, chapter:paragraph), Hebrew and English, at the design (the whole-row rule, owner-ruled 2026-09-17), each a case of a cell of cold_run_courts_prophet.py with its verdict a DATA row or a PARAMETER (the code/data separation law: the Mishnah's rows fed at run time, never written into the source). A TALMUD SEGMENT only where a Mishnah verdict is disputed and a cell needs it: NONE READ — the disputed rows (Sanhedrin 2:4's wives, Chullin 11:2's two or five and the weight, Zevachim 2:1's left hand) carry the arms on the Mishnah's own line and the cells record them all. THE FULL DOCKET OWED to the full process (COMPILE_DEBT.md's lean-pass box): the tractates the reading's finds name — Sanhedrin 1-2, 5-7, 11; Chullin 10-11; Sukkah 5; Zevachim 2; Sotah 7; Makkot 1; Bekhorot 6-7; Berakhot 1; the segments Sanhedrin 86b-89a, 20b-22a, 41a, 56a, 65a-67a, Chullin 130a-137a, Sukkah 55b-56a, Zevachim 15b-16a, Sotah 41a-b, Kiddushin 32b, Makkot 5b-6a, Bekhorot 33a, Yoma 73b.")
L.append("# THE VERDICTS: LAW names the cell and the ask of cold_run_courts_prophet.py that grades the row (F3 the_high_court, F4 the_king, F5 the_priests_dues, F6 the_levite_at_the_place, F7 the_diviners); the row's own words the case, the verdict the arms the Mishnah records. The Mishnah's rows by chapter:paragraph (the export's index).")
L.append("# COVERAGE (computed): %d of %d declared rows read whole (Hebrew %d, English %d); segments read 0; rows outside the chapters' verses 0 (Sanhedrin 2:4's optional war and Sukkah 5:7's showbread the rows' other clauses — each row read whole as the rule requires)." % (len(read), len(ROWS), sum(1 for r in read if r[3]), sum(1 for r in read if r[4])))
L.append("")
L.append("## THE EIGHT ROWS (each read whole; the verdict beside it)")
for (tr, c, p, he, en), (tr_, c_, p_, vs, where, verdict, cell, opening) in zip(read, ROWS):
    L.append("- Mishnah %s %d:%d — %s. On %s; %s. THE ROW (English, whole): %s THE HEBREW OPENS: %s. THE CELL: %s." % (tr, c, p, verdict, vs, where, en, opening, cell))
L.append("")
L.append("## CITE INDEX — every source opened, each fully named")
for tr, c, p, he, en in read:
    L.append("- Mishnah %s %d:%d (Data/sefaria_export/Mishnah_%s/he.json and en.json — chapter %d, paragraph %d; read whole)" % (tr, c, p, tr, c, p))
text = '\n'.join(L) + '\n'
open(OUT, 'w', encoding='utf-8').write(text)
print('THE LEAN EXAM WRITTEN: %s — %d bytes; %d rows read whole; segments read 0' % (OUT, len(text.encode()), len(read)))
